async function getAudit(db,{check=false,force=false,refreshRegistry=false,forceRegistry=false}={}){if(!db){const evidence=staticEvidence();return{providers:AUDIT,evidence,scope:SCOPE,watchlist:WATCHLIST,verifiedAt:VERIFIED_AT,checkResult:null,registry:{sources:[],status:"unavailable"}};}await ensureDb(db);await seedEvidence(db);let checkResult=null;if(check)checkResult=await checkNextEvidence(db,force);const rows=await db.prepare("SELECT * FROM source_evidence ORDER BY provider,family").all(),evidence=(rows.results||[]).map((x)=>({id:x.source_id,provider:x.provider,family:x.family,sourceUrl:x.source_url,cadenceHours:Number(x.cadence_hours),expectedIds:JSON.parse(x.expected_ids_json),scopeVersion:x.scope_version,reviewedAt:x.reviewed_at,lastCheckedAt:x.last_checked_at,httpStatus:x.last_http_status,driftStatus:x.drift_status,errorMessage:x.error_message})),providers=AUDIT.map((a)=>({...a,sources:evidence.filter((x)=>x.provider===a.provider)})),registry=await getRegistries(db,{refresh:refreshRegistry,force:forceRegistry});return{providers,evidence,scope:SCOPE,watchlist:WATCHLIST,verifiedAt:VERIFIED_AT,checkResult,registry};}
async function blueprints(request,db){if(!db)return Response.json({error:"Persistent storage is unavailable."},{status:503});await ensureDb(db);if(request.method==="GET"){const rows=await db.prepare("SELECT id,name,payload_json,created_at FROM application_blueprints ORDER BY created_at DESC LIMIT 50").all();return Response.json({blueprints:rows.results||[]});}if(request.method!=="POST")return new Response("Method not allowed",{status:405});const p=await request.json();if(!p||!p.name||!Array.isArray(p.features)||!p.features.length||!Array.isArray(p.routing)||!p.routing.length)return Response.json({error:"The blueprint is incomplete."},{status:400});const id=crypto.randomUUID();await db.prepare("INSERT INTO application_blueprints (id,name,payload_json,created_at) VALUES (?,?,?,?)").bind(id,String(p.name).slice(0,160),JSON.stringify(p),new Date().toISOString()).run();return Response.json({id,saved:true},{status:201});}
export default{async fetch(request,env){
  const u=new URL(request.url);
  if(u.pathname==="/api/catalog"&&request.method==="GET"){try{return Response.json({models:await getCatalog(env.DB),source:"published-registry",verifiedAt:VERIFIED_AT},{headers:{"cache-control":"no-store"}});}catch(error){return Response.json({models:CATALOG,source:"bundled-fallback",error:String(error)},{headers:{"cache-control":"no-store"}});}}
  if(u.pathname==="/api/audit"&&request.method==="GET"){try{return Response.json(await getAudit(env.DB,{check:u.searchParams.get("check")==="1",force:u.searchParams.get("force")==="1",refreshRegistry:u.searchParams.get("registry")==="1",forceRegistry:u.searchParams.get("forceRegistry")==="1"}),{headers:{"cache-control":"no-store"}});}catch(error){return Response.json({providers:AUDIT,evidence:staticEvidence(),scope:SCOPE,watchlist:WATCHLIST,registry:{sources:[],status:"error"},verifiedAt:VERIFIED_AT,source:"bundled-fallback",error:String(error)},{headers:{"cache-control":"no-store"}});}}
  if(u.pathname==="/api/registries"&&request.method==="GET"){try{return Response.json(await getRegistries(env.DB,{refresh:u.searchParams.get("refresh")==="1",force:u.searchParams.get("force")==="1"}),{headers:{"cache-control":"no-store"}});}catch(error){return Response.json({sources:[],status:"error",error:String(error)},{status:502,headers:{"cache-control":"no-store"}});}}
  if(u.pathname==="/api/registry-candidates"&&request.method==="GET"){try{return Response.json(await getRegistryCandidates(env.DB,{refresh:u.searchParams.get("refresh")==="1",force:u.searchParams.get("force")==="1",q:u.searchParams.get("q")||"",provider:u.searchParams.get("provider")||"all",sourceId:u.searchParams.get("source")||"all",classification:u.searchParams.get("classification")||"all",offset:u.searchParams.get("offset")||0,limit:u.searchParams.get("limit")||50}),{headers:{"cache-control":"no-store"}});}catch(error){return Response.json({rows:[],providers:[],sources:[],total:0,status:"error",error:String(error)},{status:502,headers:{"cache-control":"no-store"}});}}
  if(u.pathname==="/api/blueprints")return blueprints(request,env.DB);
  if(u.pathname!=="/")return new Response("Not found",{status:404});
  return new Response(renderPage(CATALOG,AUDIT),{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-cache"}});
}};
